ROOT=Path(__file__).resolve().parents[1]
sys.path[:0]=[str(ROOT),str(ROOT/'scripts'),str(ROOT/'tests')]
from pynq_w4b import service
from pynq_w4b.protocol import validate_package, RequestError
from w4b_board import validate_w4b, close_w4b, export_w4b
from verify_c7_w4_browser import browser_groups, verify
from verify_w4b_run import check_run
from browser_q4d_fixtures import HostHardware, expected_words
PACKAGE=Path(os.environ.get('W4B_PACKAGE',str(ROOT/'build/deploy/c7_w4_browser_dev02/package')))
UPLOAD=PACKAGE.parent/'upload'
BASE=Path('D:/PLD/retina_fpga/build/deploy/q4d_c7_experimental_r1')
SUITE='a'*32

def request(position=0):
    repeat,phase,index=service.formal_step(position)
    return dict(image_id='im0001',side=512,algorithm='C7',threshold=112,mode='final',png_profile='fast',
                client_nonce=f'w4b_{SUITE}_r{repeat}_{phase}{index}')

def observation(job,position):
    repeat,phase,index=service.formal_step(position);start=position*200+10
    return dict(client_nonce=job['request']['client_nonce'],config_id=job['config_id'],input_sha256=job['input']['sha256'],
        output_sha256=job['output']['sha256'],request_start_ms=start,result_received_ms=start+100,images_decoded_ms=start+110,render_done_ms=start+120,
        visibility='visible',user_agent='HOST_TEST_ONLY',loop_id=None if phase=='w' else f'{SUITE}_r{repeat}',
        loop_index=None if phase=='w' else index,loop_start_ms=None if phase=='w' else ((repeat-1)*103+3)*200+10)

def synthetic_protocol():
    """Pure metadata unit fixture, not archived board evidence."""
    records=[];observations=[]
    for i in range(309):
        r=dict(run_id=str(i),session_id='HOST_ONLY',config_id='x',request=request(i),input={'sha256':'1'},output={'sha256':'2'})
        o=observation(r,i);o.update(run_id=r['run_id'],session_id=r['session_id'],evidence_kind='PYNQ_PL_DMA',request_to_render_ms=120,result_received_to_render_ms=20)
        o['browser_actual_fps']=None if o['loop_index'] in (None,1) else o['loop_index']*1000/(o['render_done_ms']-o['loop_start_ms'])
        records.append(r);observations.append(o)
    return records,observations

class ProtocolTests(unittest.TestCase):
    def test_reference_hardware_evaluation_observer_and_inputs_preserved(self):
        m=validate_w4b(PACKAGE)
        for name in ('hardware.py','evaluation.py','quality_observer.py','__init__.py'):
            self.assertEqual((PACKAGE/'pynq_w4b'/name).read_bytes(),(BASE/'pynq_q4d'/name).read_bytes())
        for name in m['artifacts']:
            if name.startswith(('inputs/','labels/')) or name.endswith(('.bit','.hwh')) or name in ('q4d_hardware_manifest.json','a0_dma_board_test.py'):
                self.assertEqual((PACKAGE/name).read_bytes(),(BASE/name).read_bytes())

    def test_original_processor_and_display_math_unchanged(self):
        def nodes(path):return {n.name:ast.dump(n,include_attributes=False) for n in ast.parse(path.read_bytes()).body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
        original=nodes(BASE/'pynq_q4d/service.py');new=nodes(PACKAGE/'pynq_w4b/service.py')
        for name in ('process_run','encode_png'):self.assertEqual(new[name],original[name])
        old=(BASE/'ui/app.js').read_text();new=(PACKAGE/'ui/app.js').read_text()
        self.assertEqual(old[old.index('function draw('):old.index('async function runOne(')],new[new.index('function draw('):new.index('async function runOne(')])

    def test_no_cpu_comparator_in_deployment(self):
        for p in (PACKAGE/'pynq_w4b').glob('*.py'):
            for forbidden in ('system_bench','software.reference','bench_reference'):
                self.assertNotIn(forbidden,p.read_text())
            tree=ast.parse(p.read_bytes())
            self.assertFalse(any(isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='expected_words' for n in ast.walk(tree)))
        self.assertFalse((PACKAGE/'system_bench').exists())

    def test_python310_and_exact_seven_cells(self):
        nb=json.loads((UPLOAD/'c7_w4_browser.ipynb').read_bytes());cells=[c for c in nb['cells'] if c['cell_type']=='code']
        self.assertEqual(len(cells),7)
        for c in cells:ast.parse(''.join(c['source']),feature_version=(3,10))
        for p in PACKAGE.rglob('*.py'):ast.parse(p.read_bytes(),feature_version=(3,10))

    def test_fresh_extraction_and_preserve_old_folder(self):
        nb=json.loads((UPLOAD/'c7_w4_browser.ipynb').read_bytes());code=''.join(next(c for c in nb['cells'] if c['cell_type']=='code')['source'])
        cwd=Path.cwd()
        with tempfile.TemporaryDirectory() as td:
            try:
                os.chdir(td);shutil.copy2(UPLOAD/'c7_w4_browser_r1.zip',td)
                with contextlib.redirect_stdout(io.StringIO()):exec(code,{})
                validate_w4b(Path(td)/'c7_w4_browser_r1')
                with self.assertRaises(FileExistsError):exec(code,{})
                p=Path('c7_w4_browser_r1.zip');p.write_bytes(p.read_bytes()+b'bad')
                with self.assertRaisesRegex(ValueError,'Wrong package bytes'):exec(code,{})
            finally:os.chdir(cwd)

    def test_schedule_boundaries(self):
        self.assertEqual([service.formal_step(i) for i in (0,2,3,102,103,308)],[(1,'w',1),(1,'w',3),(1,'m',1),(1,'m',100),(2,'w',1),(3,'m',100)])
        for i in (-1,309,True,1.5):
            with self.assertRaises(RequestError):service.formal_step(i)

    def test_independent_summary_excludes_warmup(self):
        records,observations=synthetic_protocol();suite,groups=browser_groups(records,observations)
        self.assertEqual(suite,SUITE);self.assertEqual(len(groups),3)
        for group in groups:self.assertEqual((group['n'],group['median_ms'],group['elapsed_ms']),(100,120,19920))

    def test_hidden_missing_duplicate_wrong_nonce_and_clock_rejected(self):
        records,observations=synthetic_protocol()
        for index,key,value in [(0,'visibility','hidden'),(103,'client_nonce','changed'),(10,'loop_index',3),(308,'browser_actual_fps',999),(5,'request_start_ms',-1),(2,'loop_id','wrong'),(4,'config_id','stale')]:
            bad=copy.deepcopy(observations);bad[index][key]=value
            with self.subTest(key=key),self.assertRaises(ValueError):browser_groups(records,bad)
        with self.assertRaises(ValueError):browser_groups(records[:-1],observations[:-1])
        bad=copy.deepcopy(records);bad[5]['run_id']=bad[4]['run_id']
        with self.assertRaises(ValueError):browser_groups(bad,observations)

class NativeApplicationTests(unittest.IsolatedAsyncioTestCase):
    async def asyncSetUp(self):
        self.temp=tempfile.TemporaryDirectory();self.root=Path(self.temp.name)/'package';shutil.copytree(PACKAGE,self.root)
        self.manifest=validate_package(self.root);self.hw=HostHardware(self.root,delay=.004)
        self.m=service.FormalManager(self.root,self.manifest,self.hw)
        await asyncio.get_running_loop().run_in_executor(self.m.executor,self.hw.open)
        self.source,_=self.m.inputs.load(self.m.inputs.request(request()))
        self.golden=expected_words(self.source,3,'C7',112)
        self.cache=patch('browser_q4d_fixtures.expected_words',return_value=self.golden);self.cache.start()

    async def asyncTearDown(self):
        if self.m.pump:await self.m.pump
        self.cache.stop();self.m.executor.shutdown(wait=True);self.temp.cleanup()

    async def completed(self,i):
        job=self.m.submit(request(i));await self.m.pump;job=self.m.get(job['run_id'])
        self.assertEqual(job['status'],'COMPLETED')
        return job

    async def test_fixed_config_and_order_reject_before_dma(self):
        for key,value in [('side',256),('threshold',28),('algorithm','C5'),('png_profile','baseline'),('image_id','im0324')]:
            with self.subTest(key=key),self.assertRaises(RequestError):self.m.submit({**request(),key:value})
        with self.assertRaises(RequestError):self.m.submit(request(1))
        self.assertEqual(self.hw.buffers,[])

    async def test_requires_previous_render_and_duplicate_cannot_add_frame(self):
        job=await self.completed(0)
        self.assertEqual(self.m.submit(request(0))['run_id'],job['run_id'])
        with self.assertRaises(RequestError):self.m.submit(request(1))
        self.m.browser_timing(job['run_id'],observation(job,0))
        with self.assertRaises(service.BusyError):self.m.browser_timing(job['run_id'],observation(job,0))
        changed=request(1);changed['client_nonce']=changed['client_nonce'].replace(SUITE,'b'*32)
        with self.assertRaises(RequestError):self.m.submit(changed)
        self.assertEqual(self.hw.sequence,1)

    async def test_hidden_sample_and_incomplete_summary_rejected(self):
        job=await self.completed(0)
        with self.assertRaises(RequestError):self.m.browser_timing(job['run_id'],{**observation(job,0),'visibility':'hidden'})
        with self.assertRaises(ValueError):self.m.formal_summary()
        self.assertEqual(self.hw.sequence,1)

    async def test_dma_failure_preserves_fault_and_no_retry_or_finish(self):
        self.hw.fault='timeout';job=self.m.submit(request());await self.m.pump
        self.assertEqual(self.m.get(job['run_id'])['status'],'FAILED');self.assertEqual(self.hw.state,'FAULT');self.assertTrue(self.hw.retained)
        with self.assertRaises((RequestError,service.BusyError)):self.m.submit(request(1))
        with self.assertRaises(service.BusyError):self.m.finish()
        self.assertEqual(self.hw.downloads,1)

    async def test_full_309_host_frames_pixels_summary_closed_export(self):
        records=[];observations=[]
        for i in range(309):
            job=await self.completed(i);records.append(job)
            observations.append(self.m.browser_timing(job['run_id'],observation(job,i)))
            np.testing.assert_array_equal(np.load(self.m.directory/job['run_id']/'output_packed.npy'),self.golden)
            self.assertTrue(all(b.freed for b in self.hw.buffers));self.hw.buffers.clear();self.hw.calls.clear()
        summary=self.m.formal_summary();self.assertEqual([g['n'] for g in summary['groups']],[100]*3)
        # Explicit host-only metadata fixture exercises the independent client arithmetic.
        synthetic=[{**o,'evidence_kind':'PYNQ_PL_DMA'} for o in observations]
        self.assertEqual(browser_groups(records,synthetic)[1],summary['groups'])
        with self.assertRaises(RequestError):self.m.submit({**request(), 'client_nonce':f'w4b_{SUITE}_r3_m101'})
        class Server:
            def stop(self):pass
            async def close_all_connections(self):pass
        ctx=dict(manager=self.m,server=Server(),root=self.root,executor=self.m.executor,w4b_summary=summary)
        with contextlib.redirect_stdout(io.StringIO()):
            await close_w4b(ctx);exported=await export_w4b(ctx)
        with zipfile.ZipFile(exported) as z:
            self.assertEqual(json.loads(z.read('session.json'))['status']['service_state'],'CLOSED')
            # All 309 arrays and 1545 PNGs checked; cached *independent* golden only in HOST TEST.
            with patch('verify_w4b_run.expected_words',return_value=self.golden):
                for r in records:check_run(z,r,self.root,self.manifest)
            self.assertEqual(json.loads(z.read('capabilities.json'))['evidence_kind'],'HOST_TEST_DOUBLE_NOT_BOARD')
        # Host evidence must never pass the board verifier (supply completed synthetic Notebook only).
        nb=json.loads((UPLOAD/'c7_w4_browser.ipynb').read_bytes());markers=['W4B_PACKAGE_PASS','W4B_PRECHECK_PASS','BROWSER_SERVICE_READY','W4B_BROWSER_READY','W4B_SUMMARY_READY','W4B_CLOSED_IDLE','W4B_RESULTS_READY']
        for i,c in enumerate([c for c in nb['cells'] if c['cell_type']=='code']):c.update(execution_count=i+1,outputs=[dict(output_type='stream',name='stdout',text=[markers[i]])])
        notebook=self.root.parent/'HOST_ONLY.ipynb';notebook.write_text(json.dumps(nb))
        with self.assertRaisesRegex(ValueError,'HOST TEST is not board evidence'):verify(exported,notebook,self.root,UPLOAD/'c7_w4_browser.ipynb')
        self.assertEqual(self.hw.sequence,309)
        # A temporary SYNTHETIC metadata fixture tests the positive auditor path.
        # It is never saved as a project result and never represents board measurements.
        fake_env=dict(pynq='3.0.1',machine='armv7l',runtime_fclk0_mhz_register_readback=100.0,
            drivers={'dma':'pynq.lib.dma.DMA','control':'pynq.lib.axigpio.AxiGPIO','observer':'pynq.lib.axigpio.AxiGPIO'},
            warning='HOST SYNTHETIC AUDITOR FIXTURE ONLY')
        fake_initial=dict(session_id=self.m.session_id,completed=0,overlay_downloads=1,service_state='READY',hardware_state='IDLE')
        cells=[c for c in nb['cells'] if c['cell_type']=='code']
        cells[1]['outputs'][0]['text']=[markers[1]+'\nRuntime: '+repr(fake_env)+'\n']
        for i in (2,3):cells[i]['outputs'][0]['text']=[markers[i]+'\n'+repr(fake_initial)+'\n']
        notebook.write_text(json.dumps(nb))
        fake_zip=self.root.parent/'HOST_ONLY_SYNTHETIC_AUDITOR.zip'
        with zipfile.ZipFile(exported) as original,zipfile.ZipFile(fake_zip,'w',zipfile.ZIP_DEFLATED) as z:
            for name in original.namelist():
                data=original.read(name)
                if name.endswith(('.json','.jsonl')):data=data.replace(b'HOST_TEST_DOUBLE_NOT_BOARD',b'PYNQ_PL_DMA')
                if name=='environment.json':data=json.dumps(fake_env).encode()
                z.writestr(name,data)
        with patch('verify_w4b_run.expected_words',return_value=self.golden):
            result=verify(fake_zip,notebook,self.root,UPLOAD/'c7_w4_browser.ipynb')
        self.assertEqual(result['matched_words'],309*512*512)
        self.assertEqual(result['matched_png_images'],1545)

if __name__=='__main__':unittest.main()
